<?php require 'config/db.php'; if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: write.php');exit;} function c($v){return trim($v??'');}$title=c($_POST['title']);$author=c($_POST['author']);$email=c($_POST['email']);$excerpt=c($_POST['excerpt']);$body=c($_POST['body']);$color=in_array($_POST['color']??'',array('coral','blue','green','purple','yellow'),true)?$_POST['color']:'coral';if($title===''||$author===''||$body==='')die('Required fields are missing.');$q=$pdo->prepare("INSERT INTO stories(title,author,email,excerpt,body,color,status,created_at) VALUES(?,?,?,?,?,?, 'pending', NOW())");$q->execute([$title,$author,$email,$excerpt,$body,$color]);header('Location: write.php?sent=1');